import{_ as e,o as a,c as d,a2 as i}from"./chunks/framework.BW2T23B9.js";const b=JSON.parse('{"title":"可访问性","description":"","frontmatter":{},"headers":[],"relativePath":"guide/accessibility.md","filePath":"guide/accessibility.md","lastUpdated":1787830168000}'),r={name:"guide/accessibility.md"};function l(o,t,c,s,h,n){return a(),d("div",null,[...t[0]||(t[0]=[i('<h1 id="可访问性" tabindex="-1">可访问性 <a class="header-anchor" href="#可访问性" aria-label="Permalink to &quot;可访问性&quot;">​</a></h1><p>可访问性偏好由根应用壳统一应用，并持久化到本地设置。组件不得在局部重新解释同名设置。</p><h2 id="偏好" tabindex="-1">偏好 <a class="header-anchor" href="#偏好" aria-label="Permalink to &quot;偏好&quot;">​</a></h2><table tabindex="0"><thead><tr><th>偏好</th><th>范围</th><th>运行时效果</th></tr></thead><tbody><tr><td><code>textScale</code></td><td>100%–200%</td><td>覆盖根文本缩放</td></tr><tr><td><code>reducedMotion</code></td><td>布尔</td><td>设置 disableAnimations，减少非必要动画</td></tr><tr><td><code>highContrast</code></td><td>布尔</td><td>使用高对比明暗主题</td></tr><tr><td><code>dyslexiaFont</code></td><td>布尔</td><td>切换到 Lexend 字体体系</td></tr><tr><td><code>sensoryReduce</code></td><td>布尔</td><td>关闭音效和触觉反馈</td></tr><tr><td><code>focusMode</code></td><td>布尔</td><td>关闭旋转图、计时器等分心元素</td></tr></tbody></table><h2 id="组件要求" tabindex="-1">组件要求 <a class="header-anchor" href="#组件要求" aria-label="Permalink to &quot;组件要求&quot;">​</a></h2><ul><li>文本在 200% 缩放下不得被固定高度裁切。</li><li>交互元素需要可读名称和稳定焦点顺序。</li><li>颜色不能作为唯一状态信号。</li><li>高对比模式必须保留错误、成功和当前选择的语义区分。</li><li>减少动态效果时关闭视差、持续旋转、复杂页面过渡和非必要 3D 运动。</li><li>键盘和辅助技术应能完成与触摸相同的核心流程。</li></ul><h2 id="主题关系" tabindex="-1">主题关系 <a class="header-anchor" href="#主题关系" aria-label="Permalink to &quot;主题关系&quot;">​</a></h2><p>应用提供 light、dark、highContrastLight、highContrastDark。高对比是主题变体，不是简单提高饱和度。系统主题决定明暗时，高对比设置仍选择对应的高对比变体。</p><h2 id="音频关系" tabindex="-1">音频关系 <a class="header-anchor" href="#音频关系" aria-label="Permalink to &quot;音频关系&quot;">​</a></h2><p><code>sensoryReduce</code> 主要控制装饰音效和触觉。课程中作为题目必要输入的音频需要明确的替代方式，例如文字稿或重播控制。不能通过静音装饰效果同时让听力题失去完成路径。</p><h2 id="web-产品页" tabindex="-1">Web 产品页 <a class="header-anchor" href="#web-产品页" aria-label="Permalink to &quot;Web 产品页&quot;">​</a></h2><p>产品页单独遵循浏览器偏好：触屏设备和 <code>prefers-reduced-motion</code> 会关闭指针追踪、视差与卡片倾斜。该行为不修改客户端设置。</p><h2 id="检查表" tabindex="-1">检查表 <a class="header-anchor" href="#检查表" aria-label="Permalink to &quot;检查表&quot;">​</a></h2><ul><li>使用键盘依次访问导航、主要按钮和弹层。</li><li>在 200% 文本缩放下执行一节课。</li><li>在高对比明暗主题下检查表单和错误状态。</li><li>开启 reduced motion 后确认无持续装饰动画。</li><li>开启 sensory reduce 后确认无装饰音效与触觉。</li><li>使用屏幕阅读器确认题干、选项、评分和进度具有名称。</li></ul><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/docs/guide/settings">设置系统</a></li><li><a href="/docs/guide/audio-and-tts">音频、TTS 与朗读</a></li><li><a href="/docs/developer/testing">测试与质量门禁</a></li></ul>',16)])])}const p=e(r,[["render",l]]);export{b as __pageData,p as default};
